<script>function editStaffDoc(d,cats){const f=document.getElementById('docModal');document.getElementById('staff_doc_id').value=d.id;document.getElementById('staff_doc_title').value=d.titulo;document.getElementById('staff_doc_desc').value=d.descripcion||'';f.querySelectorAll('input[name="categorias[]"]').forEach(x=>x.checked=cats.map(Number).includes(Number(x.value)));bootstrap.Modal.getOrCreateInstance(f).show();}</script>
